INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Tends to avoid eye contact during conversations and speaks in clipped sentences. Seems perpetually anxious about something just over the horizon.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Laughs too loudly at their own jokes and slaps people on the back without warning. Quick to make friends but just as quick to forget them.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Obsessively checks their equipment before any journey, no matter how short. Has a nervous habit of counting coins repeatedly even after confirming the amount.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Speaks with absolute certainty about topics they clearly know nothing about. Rarely admits fault and always has an excuse ready.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Maintains an unsettling calm even in dangerous situations. Others find their composure either reassuring or deeply unnerving.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Complains constantly about aches, pains, and the weather, yet somehow never stops working. Misery seems to fuel their productivity.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Has a soft spot for injured animals and will stop to help them despite the impracticality. This compassion doesn''t always extend to people.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Collects small worthless trinkets and assigns them sentimental value. Becomes genuinely distressed if these items go missing.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Tells the same stories over and over, embellishing details each time. May not even remember the original truth anymore.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Refuses to sleep in the same place twice if they can help it. Claims it''s tactical, but it might just be paranoia.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Hums tunelessly while working and seems completely unaware of how irritating others find it. Genuinely confused when asked to stop.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Always eats alone and guards their food like someone might steal it at any moment. Probably has good reason for this habit.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Gives advice freely whether asked for it or not. Most of it is actually quite practical, which makes it harder to ignore.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Speaks very little but watches everything with sharp attention. When they do talk, people tend to listen.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Makes dark jokes about death and suffering as casually as discussing the weather. Uses humor to cope with things most people can''t process.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Incredibly stubborn once they''ve made up their mind about something. Would rather suffer than admit they chose poorly.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Trusts absolutely no one with anything important. Keeps backup plans for their backup plans.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Surprisingly optimistic given the state of the world. This attitude either inspires others or makes them suspicious of hidden motives.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Has a hair-trigger temper over small inconveniences but stays eerily calm during actual emergencies. Their priorities confuse most people.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Remembers every slight and favor with perfect clarity. Keeps a mental ledger that will eventually be balanced.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Fidgets constantly with whatever is in reach. Seems physically incapable of sitting still for more than a few moments.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Shares personal information far too readily with strangers. Hasn''t yet learned that openness can be dangerous.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Questions everything and trusts nothing at face value. This skepticism has kept them alive but earned few friends.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Becomes intensely focused on tasks to the point of ignoring basic needs. Has to be reminded to eat and rest.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Switches between extreme emotions without much middle ground. Either everything is wonderful or the world is ending.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Meticulously fair in all dealings and expects the same from others. Becomes genuinely offended by dishonesty even when expected.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Superstitious about seemingly random things and follows odd rituals for luck. Gets visibly uncomfortable when unable to perform them.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Brags about past accomplishments that may or may not be true. The details change depending on the audience.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Pathologically honest even when a lie would serve them better. This trait has caused as many problems as it''s solved.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('personality', 'Judges others quickly based on first impressions and rarely revises those opinions. Once you''re categorized, you stay there.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Lost everything when raiders burned down the settlement. Survived by hiding in a storage container for two days without water. Still flinches at the smell of smoke.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Grew up scrounging through ruins for scrap metal to sell. Learned early that trust gets you killed and silence keeps you breathing.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Used to work the fields until a dust storm buried the crops and half the workers with them. Decided farming wasn''t worth dying over.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Ran with a group of thieves for years before they turned on each other over a botched job. Got out with a scar and a lesson about loyalty.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Spent childhood as an unpaid laborer, breaking rocks from dawn to dusk. Escaped one night and never looked back, even when the hunger got bad.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Watched parents get dragged away by slavers while hiding in a cellar. The guilt weighs heavier than any chain ever could.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Survived three separate bandit attacks by playing dead among the corpses. Knows exactly how long to hold their breath.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Worked as a guard until realizing the people paying the wages were worse than the criminals outside the gates. Walking away seemed smarter than picking sides.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Found wandering the wasteland with no memory of the previous week. Still gets headaches when trying to remember what happened.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Earned every scar defending a caravan that didn''t pay enough to justify the wounds. Learned that honor doesn''t fill your stomach.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Grew up eating whatever could be scavenged from the trash heaps. Developed a stomach that can handle food others wouldn''t touch.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Tried to make an honest living once but discovered honest work barely covers the cost of bandages. Flexibility pays better than principles.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Saw too many friends die over petty disputes and stupid grudges. Decided survival matters more than pride.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Spent years in captivity before a random skirmish created an opportunity to slip away in the chaos. Freedom tastes better than any meal.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Used to believe in building something permanent until watching everything crumble in a single night. Keeps belongings light now.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Learned medicine by practicing on the wounded after battles, with nothing but dirty cloth and desperation. Most of them died anyway.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Crossed the wastes alone after a group abandoned them for slowing everyone down. Made it through on spite alone.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Worked security until realizing the real threats came from inside the walls, not outside. Trust became a luxury impossible to afford.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Survived a massacre by sheer chance, being in the wrong place at the right time. Wonders daily why luck picked them.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Grew up never knowing a full meal or a safe night. Hunger and fear are just background noise now, easy to ignore.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Found half-dead in the wilderness by travelers who expected gratitude. Repaid them by stealing supplies and disappearing at dawn.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Used to have ambitions of becoming something important until reality beat that foolishness out thoroughly. Staying alive is ambition enough.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Watched a plague tear through an entire settlement while the healthy fled and left the sick to rot. Learned that compassion dies when survival is at stake.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Traded years of life for skills that barely keep food on the table. Experience is just another word for accumulated suffering.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Escaped from servitude by waiting for the perfect moment of distraction. Patience proved sharper than any blade.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Lived through a famine that turned neighbors into monsters fighting over scraps. Still checks every shadow for hidden threats.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Got betrayed by someone trusted, left bleeding in a ditch over a handful of coins. Woke up angrier than hurt and twice as cautious.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Spent formative years watching the strong take from the weak without consequence. Decided which side of that equation to be on.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Survived by learning when to fight, when to run, and when to grovel. Pride is a luxury for people who can afford to die.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('backstory', 'Years of hard living shaped them into a disciplined survivor with little margin for error. Repeated setbacks taught them to adapt quickly, travel light, and avoid unnecessary commitments. They carry emotional scars but convert experience into steady judgment.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Speaks in short, clipped sentences. Wastes no words and expects the same from others.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Tends to ramble about past mistakes and lessons learned the hard way. Often trails off mid-thought before snapping back to the present.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Uses dark humor to cope with the harsh realities of survival. Laughs at things that would make others uncomfortable.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Speaks quietly and forces others to lean in to hear. Every word seems carefully measured and deliberate.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Peppers speech with crude analogies and rough comparisons. Explains everything in terms of violence or hunger.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Talks rapidly as if time is always running out. Interrupts others frequently and jumps between topics.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Adopts a matter-of-fact tone about even the most disturbing subjects. Describes atrocities like discussing the weather.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Frequently pauses to assess surroundings mid-conversation. Seems more focused on potential threats than dialogue.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Uses outdated slang and expressions that suggest a different upbringing. Refuses to explain what the terms mean.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Speaks with exhaustion evident in every syllable. Sighs heavily between sentences and sounds perpetually defeated.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Communicates through questions rather than statements. Seems incapable of making a direct declaration.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Mutters calculations and numbers under their breath between sentences. Appears to be constantly measuring odds and probabilities.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Employs unnecessarily formal language that sounds out of place. Maintains rigid grammatical structure even in casual conversation.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Repeats the last few words others say before responding. Seems to need this echo to process information.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Speaks with aggressive certainty about everything. Never admits doubt or acknowledges alternative perspectives.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Uses vague euphemisms for violence and death. Seems uncomfortable with direct language about brutal realities.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Talks to themselves as much as to others. Conducts internal debates aloud before answering questions.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Employs a slow, deliberate cadence that suggests every word costs something. Long pauses stretch between thoughts.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Constantly offers unsolicited advice about survival tactics. Cannot have a conversation without dispensing warnings.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Speaks in comparative terms, always relating current situations to worse scenarios. Everything could be more terrible.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Uses minimal vocabulary and simple sentence structure. Communicates complex ideas through basic, repetitive phrasing.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Adopts different speech patterns depending on perceived threat level. Becomes either submissive or aggressive with no middle ground.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Frequently references debts, trades, and transactions even in unrelated conversations. Views all interactions as exchanges.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Speaks as if reciting rehearsed lines. Responses sound prepared rather than spontaneous.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Interrupts own sentences with bitter commentary. Argues with their own points before finishing them.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Uses metaphors related to survival, scavenging, and endurance. Cannot describe anything without comparison to staying alive.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Maintains an artificially cheerful tone that clashes with grim subject matter. Smiles while discussing horrors.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Speaks in second person, addressing others as if narrating their actions. Describes what people are doing rather than asking.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Employs technical jargon and precise terminology even for mundane topics. Overcomplicates simple concepts.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('speechstyle', 'Trails every statement with justifications and explanations. Cannot make a claim without defending it immediately.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Wants to save enough currency to buy better equipment before the next raid season arrives. Dreams of owning armor that can actually stop a blade.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Seeks to master a craft well enough to become indispensable to others. Believes skilled hands are the only true security in this world.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Plans to gather a group of trustworthy people and establish a defensible position somewhere safer. Tired of running and hiding.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Hopes to grow strong enough to never be pushed around again. Spends every spare moment training.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Aims to stockpile enough food and medical supplies to survive an entire season without relying on anyone else. Self-sufficiency is the ultimate goal.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Wants to explore the ruins and recover ancient technology that could change everything. Believes the old world holds answers.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Determined to earn enough respect to lead others rather than always following orders. Sees potential for something better.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Seeks revenge against those who wronged them, but knows patience and preparation are necessary. Waiting for the right moment.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Dreams of owning land and building something permanent instead of wandering endlessly. Craves stability above all else.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Working toward buying freedom for themselves or someone they care about. Every day of servitude makes the goal more urgent.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Wants to learn to read and access the knowledge that others guard jealously. Information is power.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Hopes to find a place where the fighting never reaches and people can live without constant fear. Still believes such places might exist.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Determined to become wealthy enough that hunger and poverty become distant memories. Money means options.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Seeks to discover what lies beyond the known territories and document what is found there. Curiosity outweighs caution.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Plans to undermine current leadership and seize control when the opportunity presents itself. Ambition burns quietly but intensely.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Wants to heal the injured and sick, believing there is honor in preserving life in a world of death. Working to improve medical knowledge.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Aims to create a network of contacts and informants across multiple settlements. Information can be traded for safety.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Hopes to engineer better weapons or tools that could give an edge in combat. Innovation might be the key to survival.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Determined to outlive enemies and rivals through sheer stubbornness and careful planning. Survival is its own victory.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Seeks to unlock the secrets of ancient machinery and restore it to working order. The past had solutions to problems that still exist.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Wants to become fast and mobile enough to outrun any threat. Speed is survival.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Plans to accumulate resources and then disappear to start over somewhere completely unknown. Escape is the only real freedom.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Hopes to train animals for companionship and practical use in daily survival. Beasts can be more reliable than people.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Determined to build a reputation as someone never to be crossed or cheated. Fear can be protective.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Wants to become proficient with multiple weapon types to adapt to any combat situation. Versatility keeps you alive.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Plans to establish a reliable source of clean water and food production. Basic needs are never guaranteed.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Hopes to forge alliances with multiple groups to ensure backup options if things go wrong. Never rely on a single relationship.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Determined to pass on skills and knowledge to someone younger before it is too late. Legacy matters even in harsh times.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Seeks to accumulate enough medical experience to survive injuries that would kill most others. Pain is temporary but death is permanent.', '', '', '');
INSERT INTO bio_random (type, description, race, gender, faction) VALUES ('goals', 'Their long-term objective is stability built on preparation and trustworthy partnerships. Short-term decisions favor resource discipline, mobility, and avoidable-risk reduction. They measure progress by resilience, consistency, and fewer preventable losses.', '', '', '');
